## 바뀌고 난 후
```
public class MemberDAOImpl extends AbstractJDBCDAO implements MemberDAO {
	@Override
	public List<MemberVO> selectMemberList() {
		StringBuffer sql = new StringBuffer();
		sql.append(" select * from member ");
